CREATE TABLE payment_installments (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, installment_type VARCHAR(50) NOT NULL, sequence_no INT NOT NULL, due_date DATE NOT NULL, amount DECIMAL(15,2) NOT NULL, paid_amount DECIMAL(15,2) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', remarks VARCHAR(500), created_by UUID REFERENCES users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(booking_id,sequence_no));
ALTER TABLE customer_payments ADD COLUMN IF NOT EXISTS installment_id UUID REFERENCES payment_installments(id);
ALTER TABLE customer_payments ADD COLUMN IF NOT EXISTS approved_by UUID REFERENCES users(id);
ALTER TABLE customer_payments ADD COLUMN IF NOT EXISTS reversed_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE customer_payments ADD COLUMN IF NOT EXISTS reversal_reason VARCHAR(500);
CREATE TABLE payment_adjustments (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, payment_id UUID NOT NULL REFERENCES customer_payments(id), adjustment_type VARCHAR(30) NOT NULL, amount DECIMAL(15,2) NOT NULL, reason VARCHAR(500) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', created_by UUID REFERENCES users(id), approved_by UUID REFERENCES users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE bank_entries (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, entry_date DATE NOT NULL, bank_name VARCHAR(120) NOT NULL, entry_type VARCHAR(20) NOT NULL, amount DECIMAL(15,2) NOT NULL, reference_number VARCHAR(120), description VARCHAR(500), reconciled BOOLEAN NOT NULL DEFAULT FALSE, created_by UUID REFERENCES users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE collection_targets (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, month_start DATE NOT NULL, project_id UUID REFERENCES projects(id), target_amount DECIMAL(15,2) NOT NULL, achieved_amount DECIMAL(15,2) NOT NULL DEFAULT 0, created_by UUID REFERENCES users(id), UNIQUE(month_start,project_id));
CREATE INDEX idx_installments_due_status ON payment_installments(due_date,status);
CREATE INDEX idx_customer_payments_date_status ON customer_payments(payment_date,status);
